const USER = { id: "acct_marcus_01", email: "marcus@example.test" };
const SESSION_IDLE_MS = 20 * 60 * 1000;
const SESSION_ABSOLUTE_MS = 8 * 60 * 60 * 1000;
const CODE_LIFE_MS = 10 * 60 * 1000;
const MAX_FAILURES = 5;
const LOCK_MS = 15 * 60 * 1000;

type Challenge = {
  accountId: string;
  value: string;
  expires: number;
  used: boolean;
  attempts: number;
  lockedUntil: number;
};

type Session = {
  id: string;
  userId: string;
  csrf: string;
  createdAt: number;
  lastSeen: number;
  identityVerified: boolean;
  mfaVerified: boolean;
  identityChallenge?: Challenge;
  encryptedSecret?: string;
  totpAttempts: number;
  totpLockedUntil: number;
  acceptedTotpSteps: Set<number>;
  recoveryHashes: Set<string>;
  recoveryAttempts: number;
  recoveryLockedUntil: number;
