/* Requirement 3: persisted development records must never be retained under unknown
   process-local encryption keys. Stable development keys preserve data across restarts.
   Without them, the old development store is explicitly reset before it is loaded. */
if (production && (!keyMaterial || keyMaterial.length < 32 || !pepper || pepper.length < 32)) {
  console.error("MFA service cannot start: production requires MFA_MASTER_KEY and MFA_HASH_PEPPER.");
  process.exit(1);
}
if (!production && (!keyMaterial || !pepper)) {
  try {
